import { Link } from 'react-router-dom';

const Navbar = () => {
  return (
    <header>
      <div className="container"> {/* ✅ fixed lowercase */}

        <Link to="/">
          <h1>Notes System</h1>
        </Link>

        <nav>
          <Link to="/">Home</Link>
          <Link to="/about">About</Link>
        </nav>

      </div>
    </header>
  );
};

export default Navbar;
